<?phpnamespace ADMIN\AdminBundle\Entity;use Doctrine\ORM\Mapping as ORM;use Symfony\Bridge\Doctrine\Validator\Constraints\UniqueEntity;use Symfony\Component\Validator\Constraints as Assert;/** * PersonaObservada * * @ORM\Table(name="PERSONAOBSERVADA") * @ORM\Entity(repositoryClass="ADMIN\AdminBundle\Entity\PersonaObservadaRepository") * @UniqueEntity(fields={"apellido","nombre","fechaNac"},message="Error: Esta persona ya fue cargada previamente.")  */class PersonaObservada{    /**     * @var integer     *     * @ORM\Column(name="PERSONAOBSID", type="integer", nullable=false)     * @ORM\Id     * @ORM\GeneratedValue(strategy="SEQUENCE")     * @ORM\SequenceGenerator(sequenceName="PERSONAOBSERVADA_ID_SEQ", allocationSize=1, initialValue=1)     */    private $id;        /**     * @var string     *     * @ORM\Column(name="APELLIDO", type="string", length=100)     */    private $apellido;        /**     * @var string     *     * @ORM\Column(name="NOMBRE", type="string", length=100)     */    private $nombre;        /**     * @var string     *     * @ORM\Column(name="FECHANAC", type="string", length=100)     */    private $fechaNac;        /**     * @var integer     *     * @ORM\Column(name="BORRADO", type="integer")     */    private $borrado;        /**     * Many PersonaObservada has One Usuario     *     * @ORM\ManyToOne(targetEntity="\SEGURIDAD\SeguridadBundle\Entity\Usuario"))     * @ORM\JoinColumn(name="USUALTAID", referencedColumnName="USUARIOID", nullable=false)     **/    private $usuAlta;        /**     * @var \DateTime     *     * @ORM\Column(name="FECALTA", type="datetime", nullable=true)     */    private $fecAlta;        /**     * Many PersonaObservada has One Usuario     *     * @ORM\ManyToOne(targetEntity="\SEGURIDAD\SeguridadBundle\Entity\Usuario"))     * @ORM\JoinColumn(name="USUMODID", referencedColumnName="USUARIOID", nullable=false)     **/    private $usuMod;        /**     * @var \DateTime     *     * @ORM\Column(name="FECMOD", type="datetime", nullable=true)     */    private $fecMod;        /**     * @var \DateTime     *     * @ORM\Column(name="FECDESDE", type="datetime", nullable=true)     */    private $fecDesde;        /**     * @var \DateTime     *     * @ORM\Column(name="FECHASTA", type="datetime", nullable=true)     * @Assert\Date()     * @Assert\Expression(     *     "this.getFecDesde() <= this.getFecHasta()",     *     message="La fecha hasta debe ser mayor o igual a la fecha desde.")     */    private $fecHasta;        /**     * @ORM\ManyToOne(targetEntity="SEGURIDAD\SeguridadBundle\Entity\Dependencia", inversedBy="depenid" , cascade={"persist"})     * @ORM\JoinColumns({     *   @ORM\JoinColumn(name="DEPENID", referencedColumnName="DEPENID")     * })     */    private $dependencia;        /**     * @var string     *     * @ORM\Column(name="MAIL", type="string", length=1000, nullable=true)     */    private $mail;            public function __toString()    {        return $this->apellido." ".$this->nombre." ".substr($this->fechaNac,6,2)."/".substr($this->fechaNac,4,2)."/".substr($this->fechaNac,0,4);    }        /**     * Get id     *     * @return integer     */    public function getId()    {        return $this->id;            }        /**     * Set apellido     *     * @param string $apellido     * @return PersonaObservada     */    public function setApellido($apellido)    {        $this->apellido = mb_convert_case($apellido,   MB_CASE_UPPER, "UTF-8");                return $this;    }        /**     * Get apellido     * @return string     */    public function getApellido()    {        return $this->apellido;    }        /**     * Set nombre     *     * @param string $nombre     * @return PersonaObservada     */    public function setNombre($nombre)    {        $this->nombre = mb_convert_case($nombre,   MB_CASE_UPPER, "UTF-8");                return $this;    }        /**     * Get nombre     *     * @return string     */    public function getNombre()    {        return $this->nombre;    }        /**     * Set fechaNac     *     * @param integer $fechaNac     * @return PersonaObservada     */    public function setFechaNac($fechaNac)    {        $this->fechaNac = $fechaNac;                return $this;    }        /**     * Get fechaNac     *     * @return integer     */    public function getFechaNac()    {        return $this->fechaNac;    }        /**     * Set fecAlta     *     * @param \DateTime $fecAlta     * @return PersonaObservada     */    public function setFecAlta($fecAlta)    {        $this->fecAlta = $fecAlta;                return $this;    }        /**     * Get fecAlta     *     * @return \DateTime     */    public function getFecAlta()    {        return $this->fecAlta;    }        /**     * Set fecMod     *     * @param \DateTime $fecMod     * @return PersonaObservada     */    public function setFecMod($fecMod)    {        $this->fecMod = $fecMod;                return $this;    }        /**     * Get fecMod     *     * @return \DateTime     */    public function getFecMod()    {        return $this->fecMod;    }            /**     * Set usualta     *     * @param \SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario     * @return PersonaObservada     */    public function setUsuAlta(\SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario)    {        $this->usuAlta = $usuario;    }        /**     * Get usualta     *     * @return \SEGURIDAD\SeguridadBundle\Entity\Usuario     */    public function getUsuAlta()    {        return $this->usuAlta;    }        /**     * Set usumod     *     * @param \SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario     * @return PersonaObservada     */    public function setUsuMod(\SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario)    {        $this->usuMod = $usuario;    }        /**     * Get usualta     *     * @return \SEGURIDAD\SeguridadBundle\Entity\Usuario     */    public function getUsuMod()    {        return $this->usuMod;    }    /**     * @return integer     */    public function getBorrado()
    {
        return $this->borrado;    }
    /**     * @param integer $borrado     */    public function setBorrado($borrado)
    {
        $this->borrado = $borrado;    }
    /**     * Set fecDesde     *     * @param \DateTime $fecDesde     * @return PersonaObservada     */    public function setFecDesde($fecDesde)    {        $this->fecDesde = $fecDesde;                return $this;    }        /**     * Get fecDesde     *     * @return \DateTime     */    public function getFecDesde()    {        return $this->fecDesde;    }        /**     * Set fecHasta     *     * @param \DateTime $fecHasta     * @return PersonaObservada     */    public function setFecHasta($fecHasta)    {        $this->fecHasta = $fecHasta;                return $this;    }        /**     * Get fecHasta     *     * @return \DateTime     */    public function getFecHasta()    {        return $this->fecHasta;    }            /**     * Set dependencia     *     * @param \SEGURIDAD\SeguridadBundle\Entity\Dependencia $dependencia     * @return PersonaObservada     */    public function setDependencia(\SEGURIDAD\SeguridadBundle\Entity\Dependencia $dependencia = null)    {        $this->dependencia = $dependencia;                return $this;    }        /**     * Get dependencia     *     * @return \SEGURIDAD\SeguridadBundle\Entity\Dependencia     */    public function getDependencia()    {        return $this->dependencia;    }            /**     * Set mail     *     * @param string $mail     * @return Dependencia     */    public function setMail($mail)    {        $this->mail = str_replace(" ","",$mail);                return $this;    }        /**     * Get mail     *     * @return string     */    public function getMail()    {        return $this->mail;    }}